/* BrainU prototype: Principles of Robot Autonomy.
 * Plain JS, no build step. State lives in S; render() rebuilds #app from it,
 * and every clickable element carries data-act="<index into acts>".
 * Course data: prototype/course.json, generated by courses/pora/build.py. */
(function () {
  "use strict";
  const app = document.getElementById("app");
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m]));
  const trunc = (t, n) => (t.length > n ? t.slice(0, n - 1) + "…" : t);
  const KEY = "brainu-prototype-v1";

  let D = null;
  const S = { screen: "q1", pickBg: null, pickGoal: null, bg: null, goal: null, started: false, i: 0,
    done: {}, passed: 0, picked: null, checked: false, note: null, openCols: {}, notes: {},
    pg: 0, pgFrom: 0, pgDir: "", book: 0, bookDir: "", pad: 0, padDir: "", playing: false, lap: "brain",
    wrong: {}, tick: 0, today: null, focusEnd: 0, drawer: false, fx: "", pulse: null };

  // Progress survives a reload (this browser only).
  const SAVED = ["bg", "goal", "started", "i", "done", "passed", "notes", "wrong", "tick", "today", "focusEnd"];
  try { const s = JSON.parse(localStorage.getItem(KEY) || "null"); if (s) SAVED.forEach((k) => { if (k in s) S[k] = s[k]; }); } catch (e) {}
  // Goals are a list (you can want several things at once); older saves held one id.
  if (typeof S.goal === "string") S.goal = [S.goal];
  if (S.goal && !S.goal.length) S.goal = null;
  if (S.started && S.goal) S.screen = "home"; else if (S.goal) S.screen = "path";
  const save = () => { try { const o = {}; SAVED.forEach((k) => (o[k] = S[k])); localStorage.setItem(KEY, JSON.stringify(o)); } catch (e) {} };

  let acts = [];
  const act = (fn) => { acts.push(fn); return acts.length - 1; };
  const set = (patch) => { Object.assign(S, patch); save(); render(); };
  const go = (screen, extra) => {
    set(Object.assign({ screen, note: null, book: 0, bookDir: "", pad: 0, padDir: "", playing: false, drawer: false, fx: "" }, extra || {}));
    window.scrollTo({ top: 0, behavior: "instant" });
  };
  // After a page-turn animation, settle into the static end state.
  const settle = (key) => setTimeout(() => { if (S[key]) { S[key] = ""; render(); } }, 1000);

  document.addEventListener("keydown", (e) => { if (e.key === "Escape" && S.drawer) set({ drawer: false }); });
  document.addEventListener("keydown", (e) => { if ((e.key === "Enter" || e.key === " ") && e.target.matches && e.target.matches("g[data-act]")) { e.preventDefault(); e.target.dispatchEvent(new MouseEvent("click", { bubbles: true })); } });
  document.addEventListener("click", (e) => {
    const t = e.target.closest("[data-act]");
    if (!t || t.disabled) return;
    const fn = acts[+t.dataset.act];
    if (fn) { e.preventDefault(); fn(e); }
  });
  document.addEventListener("input", (e) => {
    if (e.target.id === "mynotes" && S.curId) { S.notes = Object.assign({}, S.notes, { [S.curId]: e.target.value }); save(); }
  });

  // ── course logic ──────────────────────────────────────────────────
  const ancestors = (id) => { const out = new Set(), st = [...D.C[id].p]; while (st.length) { const x = st.pop(); if (!out.has(x)) { out.add(x); st.push(...D.C[x].p); } } return out; };
  // One path that covers every goal: the union of what each goal needs, in a valid order.
  function pathFor(bgId, goals) {
    const C = D.C, bg = D.BG.find((b) => b.id === bgId) || D.BG[0], gs = [].concat(goals);
    const need = new Set(); gs.forEach((g) => { need.add(g); ancestors(g).forEach((a) => need.add(a)); });
    const keep = [...need].filter((x) => gs.indexOf(x) >= 0 || bg.k.indexOf(x) < 0);
    const chk = (x) => (C[x].c == null ? -1 : C[x].c);
    const depth = {}, dep = (x) => depth[x] ?? (depth[x] = C[x].p.length ? 1 + Math.max(...C[x].p.map(dep)) : 0);
    const keepSet = new Set(keep), out = [], seen = new Set();
    const visit = (x) => { if (seen.has(x)) return; seen.add(x); C[x].p.filter((p) => keepSet.has(p)).sort((a, b) => chk(a) - chk(b)).forEach(visit); out.push(x); };
    // Ties keep the book's own concept order (linear algebra before calculus, and so on).
    const order = {}; Object.keys(C).forEach((k, n) => (order[k] = n));
    keep.sort((a, b) => chk(a) - chk(b) || dep(a) - dep(b) || order[a] - order[b]).forEach(visit);
    return { steps: out, known: [...need].filter((x) => !keepSet.has(x)) };
  }
  const chName = (c) => (c == null ? "Assumed background" : c === 0 ? "Getting started" : "Chapter " + c + ": " + D.CH[c].title);
  const goals = () => S.goal || [];
  const nameOf = (id) => { const g = D.G.find((x) => x.id === id); return g ? g.n : D.C[id] ? D.C[id].n : ""; };
  const goalLabel = () => { const n = goals().map(nameOf); return n.length <= 2 ? n.join(" + ") : n[0] + " + " + (n.length - 1) + " more"; };
  const bgName = () => { const b = D.BG.find((x) => x.id === (S.bg || S.pickBg)); return b ? b.n : ""; };
  const path = () => (S.bg && S.goal ? pathFor(S.bg, S.goal) : { steps: [], known: [] });
  const todayKey = () => new Date().toISOString().slice(0, 10);
  const CUP = 3; // lessons in one cup of coffee
  const cupsToday = () => (S.today && S.today.d === todayKey() ? S.today.n : 0);
  const lerpHex = (a, b, t) => "#" + [0, 2, 4].map((k) => Math.round(parseInt(a.substr(k + 1, 2), 16) * (1 - t) + parseInt(b.substr(k + 1, 2), 16) * t).toString(16).padStart(2, "0")).join("");

  // ── the room's props ──────────────────────────────────────────────
  // Window: morning when you start the path, night when you finish it.
  function windowView(i, total) {
    const p = total > 1 ? i / (total - 1) : 0;
    const K = [[0, "#8fb8e8", "#ffd2a6", "#6f9a5e"], [0.3, "#3f8fe0", "#bfe3ff", "#5f8f4e"], [0.6, "#5d9ad8", "#ffe7b8", "#5b8549"], [0.82, "#4b3f7d", "#ff9466", "#3c5a3a"], [1, "#0b1030", "#2b3466", "#17242a"]];
    let a = K[0], b = K[K.length - 1];
    for (let k = 0; k < K.length - 1; k++) if (p >= K[k][0] && p <= K[k + 1][0]) { a = K[k]; b = K[k + 1]; break; }
    const t = b[0] === a[0] ? 0 : (p - a[0]) / (b[0] - a[0]), col = (n) => lerpHex(a[n], b[n], t);
    const night = p > 0.86, sx = 18 + p * 114, sy = 74 - Math.sin(Math.min(p / 0.92, 1) * Math.PI) * 52;
    const when = p < 0.2 ? "early morning" : p < 0.5 ? "midday" : p < 0.75 ? "afternoon" : p < 0.9 ? "sunset" : "night";
    const stars = night ? [[20, 14], [44, 26], [70, 10], [96, 22], [122, 12], [136, 30], [60, 36]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r=".9" fill="#fff" opacity=".85"/>`).join("") : "";
    return `<div class="window" title="It's ${when} on your path: lesson ${i + 1} of ${total}" role="img" aria-label="Window. It's ${when} on your path, lesson ${i + 1} of ${total}.">
      <svg viewBox="0 0 150 100" preserveAspectRatio="none"><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${col(1)}"/><stop offset="1" stop-color="${col(2)}"/></linearGradient></defs>
        <rect width="150" height="100" fill="url(#sky)"/>${stars}
        ${night ? `<circle cx="112" cy="22" r="8" fill="#f4f1de"/><circle cx="116" cy="19" r="7" fill="${col(1)}"/>` : `<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="8" fill="${p > 0.7 ? "#ffb35c" : "#fff2a8"}"/><circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="14" fill="#fff2a8" opacity=".25"/>`}
        <path d="M0,78 C30,62 52,70 78,64 C104,58 124,66 150,60 L150,100 L0,100 Z" fill="${col(3)}"/>
        <path d="M0,88 C40,78 80,90 150,80 L150,100 L0,100 Z" fill="${lerpHex(col(3), "#000000", 0.25)}"/>
        <path d="M75 0 V100 M0 50 H150" stroke="#e9e2d2" stroke-width="5"/></svg></div>`;
  }
  // Wall clock: the real time; tap it for a 25-minute focus timer (a red wedge).
  const clockView = () => `<div class="clockwrap"><button class="clock" aria-label="Wall clock. Tap to ${S.focusEnd > Date.now() ? "stop the" : "start a 25-minute"} focus timer" data-act="${act(() => { set({ focusEnd: S.focusEnd > Date.now() ? 0 : Date.now() + 25 * 60e3 }); tickClock(); })}">
      <svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="48" fill="#2b2d33"/><circle cx="50" cy="50" r="43" fill="#fbfaf5"/>
        <path class="clock-wedge" fill="#e2463b" opacity=".28" d=""/>
        ${Array.from({ length: 60 }, (_, k) => `<line x1="50" y1="${k % 5 ? 9.5 : 9}" x2="50" y2="${k % 5 ? 11.5 : 15}" stroke="#2b2d33" stroke-width="${k % 5 ? 0.6 : 2}" transform="rotate(${k * 6} 50 50)"/>`).join("")}
        <line class="h-hour" x1="50" y1="54" x2="50" y2="29" stroke="#1d1e22" stroke-width="3.6" stroke-linecap="round"/>
        <line class="h-min" x1="50" y1="56" x2="50" y2="15" stroke="#1d1e22" stroke-width="2.4" stroke-linecap="round"/>
        <line class="h-sec" x1="50" y1="60" x2="50" y2="13" stroke="#e2463b" stroke-width="1"/><circle cx="50" cy="50" r="2.6" fill="#e2463b"/></svg></button>
      <span class="clock-lbl"></span></div>`;
  function tickClock() {
    const el = document.querySelector(".clock"); if (!el) return;
    const now = new Date(), ms = now.getTime(), sec = now.getSeconds() + now.getMilliseconds() / 1000, min = now.getMinutes() + sec / 60, hr = (now.getHours() % 12) + min / 60;
    const rot = (q, deg) => el.querySelector(q).setAttribute("transform", `rotate(${deg.toFixed(2)} 50 50)`);
    rot(".h-hour", hr * 30); rot(".h-min", min * 6); rot(".h-sec", Math.floor(sec) * 6);
    const wedge = el.querySelector(".clock-wedge"), lbl = document.querySelector(".clock-lbl"), left = S.focusEnd - ms;
    if (left > 0) {
      const a0 = min * 6, a1 = a0 + (left / 3600e3) * 360, pt = (a) => [50 + 40 * Math.sin((a * Math.PI) / 180), 50 - 40 * Math.cos((a * Math.PI) / 180)];
      const [x0, y0] = pt(a0), [x1, y1] = pt(a1);
      wedge.setAttribute("d", `M50 50 L${x0.toFixed(2)} ${y0.toFixed(2)} A40 40 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${x1.toFixed(2)} ${y1.toFixed(2)} Z`);
      lbl.textContent = `focus · ${Math.ceil(left / 60e3)} min left`;
    } else {
      wedge.setAttribute("d", "");
      lbl.textContent = S.focusEnd && -left < 10 * 60e3 ? "focus done. take 5 ☕" : "tap for 25 min of focus";
    }
  }
  setInterval(tickClock, 1000);

  // Red string on the corkboard: pin to pin, in path order, with a little sag.
  function drawString() {
    const inn = document.querySelector(".cork-in"), svg = inn && inn.querySelector(".string");
    if (!svg) return;
    const o = inn.getBoundingClientRect();
    const pts = [...inn.querySelectorAll(".chip[data-n]")].sort((a, b) => a.dataset.n - b.dataset.n)
      .map((el) => { const r = el.getBoundingClientRect(); return [r.left - o.left + Math.min(22, r.width / 2), r.top - o.top + r.height / 2]; });
    svg.setAttribute("width", inn.scrollWidth); svg.setAttribute("height", inn.scrollHeight);
    let d = "";
    pts.forEach(([x, y], k) => { if (!k) { d = `M${x.toFixed(1)},${y.toFixed(1)}`; return; } const [px, py] = pts[k - 1], dist = Math.hypot(x - px, y - py);
      d += ` Q${((px + x) / 2).toFixed(1)},${(Math.max(py, y) + 6 + dist * 0.14).toFixed(1)} ${x.toFixed(1)},${y.toFixed(1)}`; });
    const pins = pts.map(([x, y]) => `<circle cx="${x.toFixed(1)}" cy="${(y + 1.5).toFixed(1)}" r="5" fill="rgba(0,0,0,.3)"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4.6" fill="#d6332a"/><circle cx="${(x - 1.4).toFixed(1)}" cy="${(y - 1.6).toFixed(1)}" r="1.5" fill="#ff9a8f"/>`).join("");
    svg.innerHTML = `<path d="${d}" fill="none" stroke="rgba(0,0,0,.28)" stroke-width="2.2" transform="translate(1.5 2.5)"/><path d="${d}" fill="none" stroke="#c4221c" stroke-width="1.8"/>${pins}`;
  }
  window.addEventListener("resize", () => requestAnimationFrame(drawString));
  if (document.fonts) document.fonts.ready.then(() => drawString());

  // On "Next", an eraser sweeps the board before the next lesson is written in.
  const eraseThen = (fn) => {
    const b = document.querySelector(".board");
    if (!b || (window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches)) return fn();
    if (b.classList.contains("erasing")) return;
    if (b.getBoundingClientRect().bottom < 120) window.scrollTo({ top: 0, behavior: "smooth" });
    b.classList.add("erasing"); b.insertAdjacentHTML("beforeend", '<span class="wiper" aria-hidden="true"></span>');
    setTimeout(fn, 1000);
  };

  function exportNotes(steps) {
    const ids = steps.concat(Object.keys(S.notes || {}).filter((k) => steps.indexOf(k) < 0)).filter((k) => (S.notes[k] || "").trim() && D.C[k]);
    const md = `# BrainU notes: ${goalLabel()}\n\n` + ids.map((k) => `## ${D.C[k].n}\n\n${S.notes[k].trim()}\n`).join("\n");
    const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([md], { type: "text/markdown" })); a.download = "brainu-notes.md";
    document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  }

  // ── views ─────────────────────────────────────────────────────────
  function nav() {
    const cur = (on) => (on ? ' aria-current="page"' : "");
    const home = act(() => go(S.goal ? "home" : "q1"));
    return `<nav class="am-nav top" aria-label="Main"><button class="am-nav__brand navb brandb" aria-label="BrainU home" data-act="${home}">BrainU</button><div class="am-nav__links">
      <button class="am-nav__link navb"${cur(["home", "q1", "q2", "done"].includes(S.screen))} data-act="${home}">⌂ Home</button>
      <button class="am-nav__link navb"${cur(S.screen === "path")} data-act="${act(() => go(S.goal ? "path" : "q1"))}">My path</button>
      <button class="am-nav__link navb"${cur(S.screen === "lesson")} data-act="${act(() => (S.goal ? go("lesson", { started: true }) : go("q1")))}">My lesson</button>
      <button class="am-nav__link navb"${cur(S.screen === "explore")} data-act="${act(() => go("explore"))}">Explore</button>
    </div></nav>`;
  }

  function home() {
    const { steps } = path(), i = Math.min(S.i, steps.length - 1), c = D.C[steps[i]];
    return `<main style="max-width:760px;margin:0 auto;padding:64px 24px;display:flex;flex-direction:column;gap:22px;">
      <span class="hand" style="font-size:24px;opacity:.8;">${S.started ? "welcome back" : "your path is ready"}</span>
      <section class="am-card" style="display:flex;flex-direction:column;gap:12px;">
        <span class="lbl">${esc(goalLabel())} · lesson ${i + 1} of ${steps.length}</span>
        <h1 class="am-card__title" style="margin:0;font-size:40px;">${esc(c.n)}</h1>
        <p style="margin:0;font-size:16px;line-height:1.5;">${esc(c.s)}</p>
        <div style="display:flex;flex-wrap:wrap;gap:14px 22px;align-items:center;margin-top:6px;">
          <button class="am-button" data-act="${act(() => go("lesson", { started: true }))}">${S.started ? "Continue" : "Start"} lesson ${i + 1} →</button>
          <button class="navb hand link" style="font-size:21px;" data-act="${act(() => go("path"))}">see my path</button>
        </div>
      </section>
      <button class="navb hand link" style="align-self:flex-start;font-size:21px;" data-act="${act(() => go("q1", { pickBg: S.bg, pickGoal: S.goal }))}">change my goals</button>
    </main>`;
  }

  function questions() {
    const q2 = S.screen === "q2", list = q2 ? D.G : D.BG, picked = S.pickGoal || [];
    const sel = q2 ? picked.length > 0 : S.pickBg, isOn = (id) => (q2 ? picked.indexOf(id) >= 0 : id === S.pickBg);
    const toggle = (id) => set({ pickGoal: isOn(id) ? picked.filter((x) => x !== id) : picked.concat(id) });
    const choices = list.map((o) => `<button class="pick ${isOn(o.id) ? "pick-on" : ""}" role="${q2 ? "checkbox" : "radio"}" aria-checked="${isOn(o.id)}" data-act="${act(() => (q2 ? toggle(o.id) : set({ pickBg: o.id })))}"><span class="circ${q2 ? " sq" : ""}">${isOn(o.id) ? "✓" : ""}</span><span><b>${esc(o.n)}</b><span class="d">${esc(o.b)}</span></span></button>`).join("");
    const lessons = q2 && picked.length ? pathFor(S.pickBg, picked).steps.length : 0;
    const nextAct = act(() => (q2 ? go("path", { bg: S.pickBg, goal: S.pickGoal, i: 0, started: false, done: {}, passed: 0, picked: null, checked: false, openCols: {} }) : go("q2")));
    return `<main style="max-width:1240px;margin:0 auto;padding:32px 24px 56px;display:flex;flex-direction:column;gap:24px;">
      <header style="display:flex;flex-direction:column;gap:6px;align-items:center;text-align:center;">
        <span class="hand" style="font-size:22px;opacity:.8;">an unofficial study companion to</span>
        <h1 style="margin:0;font:400 clamp(34px,5vw,54px)/1 var(--am-font-display);letter-spacing:.01em;">Principles of Robot Autonomy</h1>
        <p style="margin:6px 0 0;font-size:16px;">Answer two questions and get a short path of lessons, made for you.</p>
      </header>
      <div style="display:flex;flex-wrap:wrap;gap:28px;align-items:flex-start;justify-content:center;">
        <section class="am-card" aria-labelledby="qh" style="flex:1 1 460px;max-width:620px;min-width:0;display:flex;flex-direction:column;gap:8px;">
          <span class="lbl">Question ${q2 ? 2 : 1} of 2</span>
          ${q2 ? `<div class="hand" style="font-size:20px;display:flex;gap:10px;align-items:baseline;"><span>starting from: <b>${esc(bgName())}</b></span><button class="navb hand link" style="font-size:20px;" data-act="${act(() => go("q1"))}">change</button></div>` : ""}
          <h2 id="qh" class="am-card__title" style="margin:0 0 6px;font-size:32px;">${q2 ? "What do you want to be able to do?" : "Where are you starting from?"}</h2>
          ${q2 ? `<span class="hand" style="font-size:20px;opacity:.8;margin-top:-6px;">pick as many as you like</span>` : ""}<div class="picks" role="${q2 ? "group" : "radiogroup"}" aria-labelledby="qh">${choices}</div>
          <div style="display:flex;flex-wrap:wrap;align-items:center;gap:12px 20px;margin-top:10px;">
            <button class="am-button" ${sel ? "" : "disabled"} data-act="${nextAct}">${q2 ? "Show my path →" : "Next question →"}</button>
            <span class="hand" style="font-size:19px;opacity:.75;">${q2 ? (sel ? picked.length + " goal" + (picked.length > 1 ? "s" : "") + " · " + lessons + " lessons, in order" : "pick at least one to continue") : sel ? "one more question after this" : "pick one to continue"}</span>
          </div>
        </section>
        ${courseNotebook()}
      </div>
    </main>`;
  }

  // The whole course as a clipped notebook: pages flip up over the clip; post-it tabs jump to a part.
  function courseNotebook() {
    const now = S.pg, flip = (k) => { if (k !== now) { set({ pg: k, pgFrom: now, pgDir: k > now ? "fwd" : "back" }); settle("pgDir"); } };
    const secs = D.PARTS.map((p, ci) => ({
      t: p.t, kick: ci === 0 ? "BEFORE YOU START" : "PART " + ["I", "II", "III", "IV"][ci - 1],
      count: Object.values(D.C).filter((c) => p.chs.indexOf(c.c) >= 0).length,
      chapters: p.chs.map((n) => { const names = Object.values(D.C).filter((c) => c.c === n).map((c) => c.n); return names.length ? { label: n == null ? "The math the book assumes" : n === 0 ? "Getting started" : "Ch " + n + " · " + D.CH[n].title, names: names.join(", ") } : null; }).filter(Boolean),
    }));
    const n = secs.length + 1;
    const cls = (k) => {
      if (S.pgDir === "fwd" && k >= S.pgFrom && k < now) return "leafv-fwd";
      if (S.pgDir === "back" && k >= now && k < S.pgFrom) return "leafv-back";
      return k < now ? "leafv-gone" : k === now ? "" : "leafv-under";
    };
    const foot = (k) => `<div class="pgfoot"><button ${k === 0 ? "disabled" : ""} data-act="${act(() => flip(k - 1))}">‹ back</button><span style="opacity:.7;">page ${k + 1} of ${n}</span><button ${k === n - 1 ? "disabled" : ""} data-act="${act(() => flip(k + 1))}">flip ›</button></div>`;
    const total = Object.keys(D.C).length;
    const cover = `<section class="leafv ruled ${cls(0)}" style="z-index:${10 + n}" aria-hidden="${now !== 0}" aria-label="The whole course"><div class="pgin">
      <span class="kick">PRINCIPLES OF ROBOT AUTONOMY</span><h3>The whole course</h3>
      <span class="hw">${total} concepts in ${secs.length} parts. Flip through:</span>
      ${secs.map((s, k) => `<button class="toc" data-act="${act(() => flip(k + 1))}"><span class="toc-n">${esc(s.t)}</span><span class="toc-dots"></span><span>${s.count}</span></button>`).join("")}
      <span class="hw" style="opacity:.75;">your path lights up after the second question</span>${foot(0)}</div></section>`;
    const pages = secs.map((s, k) => `<section class="leafv ruled ${cls(k + 1)}" style="z-index:${10 + n - k - 1}" aria-hidden="${now !== k + 1}" aria-label="${esc(s.t)}"><div class="pgin">
      <span class="kick">${s.kick}</span><h3>${esc(s.t)}</h3><span class="hw" style="opacity:.75;">${s.count} concepts</span>
      ${s.chapters.map((c) => `<div><div class="chap">${esc(c.label)}</div><div class="names">${esc(c.names)}</div></div>`).join("")}${foot(k + 1)}</div></section>`).join("");
    const colors = ["#fff3a8", "#ffc8d6", "#bfe3ff", "#c9f2c7", "#ffd9a8", "#e3d4ff"];
    const names = ["Contents", "Math", "Control", "Perception", "Mapping", "Decisions"];
    const tabs = names.slice(0, n).map((l, k) => `<button class="tab ${k === now ? "tab-on" : ""}" role="tab" aria-selected="${k === now}" style="background:${colors[k]};rotate:${k % 2 ? "1deg" : "-1deg"};" data-act="${act(() => flip(k))}">${l}</button>`).join("");
    return `<aside aria-label="The whole course, as a notebook" style="flex:1 1 340px;max-width:470px;min-width:0;padding:26px 90px 8px 0;">
      <div class="flipstack" style="height:520px;">
        <svg class="clip" aria-hidden="true" viewBox="0 0 34 78"><path d="M10 70 V14 a7 7 0 0 1 14 0 V60 a4.5 4.5 0 0 1 -9 0 V20" fill="none" stroke="#8b919b" stroke-width="3" stroke-linecap="round"/></svg>
        <div class="tabs" role="tablist" aria-label="Sections">${tabs}</div>${cover}${pages}
      </div></aside>`;
  }

  function pathScreen() {
    const P = path(), steps = P.steps, pos = {}, i = Math.min(S.i, steps.length - 1);
    steps.forEach((id, k) => (pos[id] = k));
    const C = D.C, known = new Set(P.known);
    const lec = steps.reduce((n, id) => n + C[id].L.length, 0), nb = steps.reduce((n, id) => n + C[id].N.length, 0);
    const list = steps.map((id, k) => {
      const c = C[id], dn = !!S.done[id], next = S.started ? k === i : k === 0;
      const bits = [c.L.length ? c.L.length + " lecture" + (c.L.length > 1 ? "s" : "") : "", c.N.length ? c.N.length + " notebook" + (c.N.length > 1 ? "s" : "") : ""].filter(Boolean);
      return `<li><button class="step ${dn ? "step-done" : next ? "step-next" : ""}" data-act="${act(() => go("lesson", { i: k, started: true, picked: null, checked: false }))}"><span class="sn">${dn ? "✓" : k + 1 + "."}</span><span><span class="sname">${esc(c.n)}</span><span class="smeta">${c.c == null ? "background" : "ch " + c.c}${bits.length ? " · " + bits.join(" · ") : " · reading"}</span></span></button></li>`;
    }).join("");
    const cols = D.PARTS.map((p, ci) => {
      const groups = p.chs.map((n) => {
        const items = Object.entries(C).filter(([, c]) => c.c === n);
        if (!items.length) return "";
        return `<div style="display:flex;flex-direction:column;gap:4px;margin-bottom:6px;"><div class="chl">${n == null ? "" : n === 0 ? "GETTING STARTED" : esc(trunc("CH " + n + " · " + D.CH[n].title.toUpperCase(), 32))}</div>
          ${items.map(([id, c]) => `<button ${id in pos ? `data-n="${pos[id]}"` : ""} class="chip ${goals().indexOf(id) >= 0 ? "chip-goal" : id in pos ? "chip-path" : known.has(id) ? "chip-known" : "chip-dim"}" title="${esc(c.n)}" data-act="${act(() => set({ note: id }))}"><span class="num">${id in pos ? pos[id] + 1 : ""}</span><span>${esc(trunc(c.n, 26))}</span></button>`).join("")}</div>`;
      }).join("");
      const ids = Object.keys(C).filter((id) => p.chs.indexOf(C[id].c) >= 0), onPath = ids.some((id) => id in pos), open = onPath || S.openCols[ci];
      const sub = ci === 0 ? "MATH THE BOOK ASSUMES" : "PART " + ["I", "II", "III", "IV"][ci - 1];
      return `<div style="${open ? "flex:1 1 170px;min-width:160px;" : "flex:0 1 150px;min-width:120px;"}display:flex;flex-direction:column;gap:4px;"><div class="colsub">${sub}</div><div class="coltitle">${esc(p.t)}</div>
        ${open ? groups : `<button class="navb" style="text-align:left;padding:8px 10px;border-radius:6px;background:rgba(255,252,244,.7);font:500 12.5px 'Work Sans',sans-serif;color:#22201c;" data-act="${act(() => set({ openCols: Object.assign({}, S.openCols, { [ci]: true }) }))}">${ids.length} concepts, not on this path. Show</button>`}</div>`;
    }).join("");
    let note = "";
    if (S.note) {
      const c = C[S.note], far = pathFor(S.bg, S.note).steps.length;
      note = `<div class="am-card" data-medium="marker" style="padding:16px 18px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 18px;">
        <div style="display:flex;flex-direction:column;gap:2px;"><b style="font:400 22px var(--am-font-display);">${esc(c.n)}</b><span class="hand" style="font-size:19px;">${esc(chName(c.c))} · ${S.note in pos ? "lesson " + (pos[S.note] + 1) + " on your path" : far + " lessons from where you are"}</span></div>
        <div style="display:flex;align-items:center;gap:14px;">${goals().indexOf(S.note) < 0 ? `<button class="am-button" data-act="${act(() => go("path", { goal: goals().concat(S.note), i: 0, started: false, picked: null, checked: false, openCols: {} }))}">Add as a goal</button>` : goals().length > 1 ? `<button class="am-button am--secondary" data-act="${act(() => go("path", { goal: goals().filter((g) => g !== S.note), i: 0, started: false, picked: null, checked: false, openCols: {} }))}">Remove this goal</button>` : ""}
        <button class="navb hand link" style="font-size:20px;" data-act="${act(() => set({ note: null }))}">close</button></div></div>`;
    }
    return `<main style="max-width:1400px;margin:0 auto;padding:28px 24px 56px;display:flex;flex-wrap:wrap;gap:26px;align-items:flex-start;">
      <section class="am-card" aria-labelledby="ph" style="flex:1 1 340px;max-width:420px;min-width:0;display:flex;flex-direction:column;gap:6px;">
        <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;"><span class="lbl">Your path</span><button class="navb hand link" style="font-size:20px;" data-act="${act(() => go("q1", { pickBg: S.bg, pickGoal: S.goal }))}">change answers</button></div>
        <h1 id="ph" class="am-card__title" style="margin:0;font-size:32px;">${esc(goalLabel())}</h1>
        <span class="hand" style="font-size:20px;opacity:.8;">from: ${esc(bgName())} · ${steps.length} lessons · ${lec} lectures · ${nb} notebooks</span>
        <ol style="list-style:none;margin:8px 0 0;padding:0;display:flex;flex-direction:column;">${list}</ol>
        <button class="am-button" style="align-self:flex-start;margin-top:12px;" data-act="${act(() => go("lesson", { started: true }))}">${S.started ? "Continue lesson " + (i + 1) + " →" : "Start lesson 1 →"}</button>
      </section>
      <section class="cork" aria-labelledby="mh">
        <div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:6px 16px;"><h2 id="mh" class="cork-title">Where your path goes</h2>
          <div class="cork-legend">
            <span style="display:flex;align-items:center;gap:5px;"><span class="lg lg-path"></span>your lessons, pinned in order</span>
            <span style="display:flex;align-items:center;gap:5px;"><span class="lg lg-goal"></span>goal</span>
            <span style="display:flex;align-items:center;gap:5px;"><span class="lg lg-known"></span>you know it</span></div></div>
        ${note}
        <div class="cork-scroll"><div class="cork-in">${cols}<svg class="string" aria-hidden="true"></svg></div></div>
        <p class="cork-tip">Follow the red string. Tap any card to see how far it is from where you are.</p>
      </section></main>`;
  }

  function lesson() {
    const C = D.C, { steps } = path(), total = steps.length, i = Math.min(S.i, total - 1), id = steps[i], c = C[id];
    S.curId = id;
    const prev = i > 0 ? C[steps[i - 1]] : null, next = i < total - 1 ? C[steps[i + 1]] : null;
    const [qq, choices, correct, why] = c.q, ok = S.picked === correct;
    const chShort = c.c == null ? "assumed background" : c.c === 0 ? "getting started" : "chapter " + c.c;
    const L = c.L[0], nbk = c.N[0], ch = c.c == null ? null : D.CH[c.c];

    // Chalkboard
    const yt = L && (String(L.url).match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/) || [])[1];
    const screenInner = S.playing && yt
      ? `<iframe src="https://www.youtube-nocookie.com/embed/${yt}?autoplay=1&rel=0&modestbranding=1" title="${esc(L.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`
      : `<span class="thumb" style="background-image:url('https://i.ytimg.com/vi/${yt}/hqdefault.jpg')"></span><button class="play" aria-label="Play ${esc(L ? L.title : "")}" data-act="${act(() => set({ playing: true }))}">▶</button>`;
    const video = L ? `<div style="position:relative;">
        <div class="screen"><span class="tape" style="top:-10px;left:14px;transform:rotate(-8deg);"></span><span class="tape" style="top:-10px;right:14px;transform:rotate(7deg);"></span><div class="screen-in">${screenInner}</div></div>
        <svg class="arrow" aria-hidden="true" viewBox="0 0 120 60"><path d="M110 50 C 80 52, 50 40, 20 12 M20 12 l 3 14 M20 12 l 13 4" fill="none" stroke="rgba(255,255,255,.8)" stroke-width="3" stroke-linecap="round"/></svg></div>
      <span class="ch-t" style="margin-top:14px;">watch: <b>${esc(L.title)}</b> (Stanford ${esc(L.course)} · lecture ${L.n}) <a href="${esc(L.url)}" target="_blank" rel="noopener" style="opacity:.8;">↗</a></span>`
      : `<p class="ch-t" style="margin:8px 0 0;">No lecture for this one. Start with the key ideas, then read the chapter in the textbook below.</p>`;
    const planItems = (L ? ["watch the lecture"] : []).concat(["read the key ideas", "try the experiment", "pop quiz"]);
    const plan = planItems.map((t, k) => { const d = k === planItems.length - 1 && S.checked; return `<div class="ch-t ${d ? "plan-done" : ""}"><span class="box">${d ? "✓" : ""}</span>${t}</div>`; }).join("");
    const opts = choices.map((t, k) => {
      const cls = S.checked ? (k === correct ? "qopt-right" : k === S.picked ? "qopt-wrong" : "") : S.picked === k ? "qopt-on" : "";
      const mark = S.checked ? (k === correct ? "✓" : k === S.picked ? "✗" : "ABCD"[k]) : "ABCD"[k];
      return `<button class="qopt ${cls}" role="radio" aria-checked="${S.picked === k}" ${S.checked ? "disabled" : ""} data-act="${act(() => set({ picked: k }))}"><span class="qm">${mark}</span><span>${esc(t)}</span></button>`;
    }).join("");

    // Textbook
    const folio = 10 + 2 * i;
    const chapKick = c.c == null ? "BEFORE YOU START" : c.c === 0 ? "GETTING STARTED" : "CHAPTER " + c.c;
    const chapTitle = c.c == null ? "The math the book assumes" : ch.title;
    const chapUrl = ch ? ch.url : "https://porabook.com/book/";
    const exercise = `<span class="bkick">EXERCISE</span><div class="exbox"><b>Try it</b><br>${esc(c.t)}</div><p style="font-style:italic;opacity:.8;">Run it on the laptop (experiment tab), or work it by hand first.</p>`;
    const leafCls = S.book === 1 ? (S.bookDir === "fwd" ? "leafb-fwd" : "leafb-turned") : S.bookDir === "back" ? "leafb-back" : "";
    const turnFwd = act(() => { set({ book: 1, bookDir: "fwd" }); settle("bookDir"); });
    const turnBack = act(() => { set({ book: 0, bookDir: "back" }); settle("bookDir"); });

    // Notepad
    const pad0 = S.pad === 1 ? (S.padDir === "fwd" ? "leafv-fwd" : "leafv-gone") : S.padDir === "back" ? "leafv-back" : "";
    const pad1 = S.pad === 1 ? "" : "leafv-under";
    const padFwd = act(() => { set({ pad: 1, padDir: "fwd" }); settle("padDir"); });
    const padBack = act(() => { set({ pad: 0, padDir: "back" }); settle("padDir"); });

    // Bottom bar
    const advance = () => { if (next) { go("lesson", { i: i + 1, picked: null, checked: false, fx: "write" }); settle("fx"); } else go("done", { started: false }); };
    const mainLabel = !S.checked ? (S.picked === null ? "Answer the pop quiz" : "Check your answer") : next ? "Next: " + trunc(next.n, 28) + " →" : "Finish the path ★";
    const main = act(() => {
      if (S.checked) return eraseThen(advance);
      // A miss goes up as a sticky note on the board; it's due again two quizzes later.
      const wrong = Object.assign({}, S.wrong); if (ok) delete wrong[id]; else wrong[id] = { at: S.tick + 1 };
      set({ checked: true, done: ok ? Object.assign({}, S.done, { [id]: true }) : S.done, passed: S.passed + (ok ? 1 : 0),
        wrong, tick: S.tick + 1, today: { d: todayKey(), n: cupsToday() + 1 }, pulse: ok ? i : null });
      if (ok) setTimeout(() => (S.pulse = null), 1800);
    });
    const segs = steps.map((sid, k) => `<li><button class="seg ${k < i ? "seg-past" : k === i ? "seg-on" : ""}" aria-label="Lesson ${k + 1}: ${esc(C[sid].n)}" title="${k + 1}. ${esc(C[sid].n)}" data-act="${act(() => go("lesson", { i: k, picked: null, checked: false }))}"></button></li>`).join("");

    const wrongIds = Object.keys(S.wrong || {}).filter((w) => steps.indexOf(w) >= 0);
    const stickies = wrongIds.length ? `<div class="stickies" aria-label="Questions to retry">${wrongIds.slice(0, 4).map((w, k) => {
      const ago = S.tick - S.wrong[w].at, due = ago >= 2, left = 2 - ago;
      return `<button class="sticky ${due ? "sticky-due" : ""}" style="rotate:${[-4, 3, -2, 5][k]}deg;" data-act="${act(() => go("lesson", { i: steps.indexOf(w), picked: null, checked: false }))}"><span class="sticky-k">${due ? "retry now!" : "retry in " + left + " lesson" + (left > 1 ? "s" : "")}</span>${esc(trunc(C[w].n, 40))}</button>`;
    }).join("")}${wrongIds.length > 4 ? `<span class="sticky-more">+${wrongIds.length - 4} more</span>` : ""}</div>` : "";
    const notedIds = steps.filter((k) => ((S.notes || {})[k] || "").trim());
    const drawer = S.drawer ? `<div class="drawer-scrim" data-act="${act(() => set({ drawer: false }))}"></div>
      <section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dh"><div class="drawer-head"><h2 id="dh">Your notes drawer</h2>
        <div style="display:flex;gap:10px;align-items:center;">${notedIds.length ? `<button class="am-button" data-act="${act(() => exportNotes(steps))}">Export as Markdown</button>` : ""}<button class="am-button am--secondary" data-act="${act(() => set({ drawer: false }))}">Close</button></div></div>
        <div class="drawer-pages">${notedIds.length ? notedIds.map((k, n) => `<article class="torn ruled" style="rotate:${[-1.5, 1, -0.5, 1.8, -1][n % 5]}deg;"><div class="pgin"><span class="hw" style="opacity:.6;">lesson ${steps.indexOf(k) + 1}</span><h3>${esc(C[k].n)}</h3><p>${esc(S.notes[k])}</p></div></article>`).join("")
          : `<p class="hand" style="font-size:24px;color:#fff6e6;">Nothing in here yet. Write on your notepad and the page lands here.</p>`}</div></section>` : "";
    const learnedToday = cupsToday(), level = Math.max(0, 1 - learnedToday / CUP), lvlY = 30 + (1 - level) * 44;
    const mug = `<div class="mugwrap"><button class="mug" aria-label="Coffee mug, ${learnedToday} of ${CUP} lessons today. ${level ? "" : "Tap to refill."}" data-act="${act(() => set({ today: { d: todayKey(), n: 0 } }))}">
      <svg viewBox="0 0 96 100" aria-hidden="true"><ellipse cx="44" cy="90" rx="40" ry="7" fill="rgba(0,0,0,.28)"/><ellipse cx="44" cy="86" rx="38" ry="7" fill="#efe9dc"/>
        ${level ? `<g class="steam" fill="none" stroke="rgba(255,255,255,.7)" stroke-width="2.4" stroke-linecap="round"><path d="M32 22 c-6 -6 6 -10 0 -18"/><path d="M46 20 c-6 -6 6 -10 0 -18"/><path d="M58 22 c-6 -6 6 -10 0 -18"/></g>` : ""}
        <path d="M70 40 c18 0 18 28 0 28" fill="none" stroke="#d9d2c3" stroke-width="7"/>
        <path d="M14 28 h60 v44 c0 10 -8 14 -16 14 h-28 c-8 0 -16 -4 -16 -14 z" fill="#f4efe4"/>
        <clipPath id="cup"><path d="M18 30 h52 v42 c0 8 -6 11 -13 11 h-26 c-7 0 -13 -3 -13 -11 z"/></clipPath>
        <g clip-path="url(#cup)"><rect x="14" y="${lvlY.toFixed(1)}" width="60" height="60" fill="#4a2c17"/><ellipse cx="44" cy="${lvlY.toFixed(1)}" rx="27" ry="3.2" fill="#8a5a33"/></g>
        <ellipse cx="44" cy="28" rx="30" ry="4.5" fill="none" stroke="#d9d2c3" stroke-width="2"/><path d="M14 46 h60" stroke="#2f6f8f" stroke-width="5" opacity=".8"/></svg></button>
      <p class="thing-label" style="text-align:center;margin:4px 0 0;">${level ? `coffee · ${learnedToday} of ${CUP} lessons today` : "empty. take a break? tap to refill"}</p></div>`;

    return `<div class="wall"><div class="wall-top">${windowView(i, total)}${clockView()}</div><div class="frame">
      ${stickies}
      <section class="board slate ${S.fx === "write" ? "writein" : ""}" aria-label="Chalkboard: ${esc(c.n)}">
        <div class="bhead"><span class="ch-t" style="opacity:.8;">today · ${chShort} · lesson ${i + 1} of ${total}</span><div class="plan" aria-label="Lesson plan">${plan}</div></div>
        <div><h1 class="ch-big">${esc(c.n)}</h1>${video}</div>
        <div><h2 class="ch-h ch-u">key ideas</h2>${c.i.map((t, k) => `<div class="idea"><b>${k + 1}.</b><p>${esc(t)}</p></div>`).join("")}${prev ? `<div class="ch-t" style="opacity:.75;">builds on: ${esc(prev.n)}</div>` : ""}</div>
        <div class="quiz"><h2 class="ch-h" style="margin-bottom:6px;">pop quiz!</h2><p style="margin:0 0 6px;">${esc(qq)}</p>
          <div role="radiogroup" aria-label="Pop quiz answers" style="display:flex;flex-direction:column;gap:2px;">${opts}</div>
          ${S.checked ? `<p role="status" style="margin:8px 0 0;"><b style="font:700 22px 'Caveat',cursive;">${ok ? "Correct!" : "Not quite. It's on a sticky note now."}</b> ${esc(why)}</p>` : ""}</div>
      </section>
      <div class="tray" aria-hidden="true"><span class="stick" style="left:12%;width:48px;"></span><span class="stick" style="left:17%;width:30px;transform:rotate(-5deg);"></span><span class="stick" style="left:64%;width:24px;background:#f6c9c9;"></span><span class="eraser" style="left:78%;"></span></div>
    </div></div>

    <div class="desk"><div class="desk-row">
      <div><p class="thing-label">the textbook</p>
        <div class="book" aria-label="Textbook, ${esc(chName(c.c))}">
          <div class="cover" aria-hidden="true"></div>
          <div class="bpage bpage-l"><div class="bin">
            ${S.book === 1 ? exercise : `<span class="bkick">${chapKick}</span><h4 style="font-size:26px;">${esc(chapTitle)}</h4><p style="font-style:italic;opacity:.8;">Principles of Robot Autonomy</p>`}
            <div class="bfolio"><span>${folio}</span>${S.book === 1 ? `<button data-act="${turnBack}">‹ turn back</button>` : ""}</div></div></div>
          <div class="bpage bpage-r"><div class="bin"><span class="bkick">GO DEEPER</span><h4>Read the full chapter</h4>
            <p>The whole of ${esc(chName(c.c))} is free to read online, with Ask the Book to answer questions as you go.</p>
            <div class="bfolio"><a href="${esc(chapUrl)}" target="_blank" rel="noopener">Open on porabook.com ↗</a><span>${folio + 3}</span></div></div></div>
          <div class="leafb ${leafCls}">
            <div class="face face-front"><div class="bin"><span class="bkick">READING</span><h4>${esc(c.n)}</h4><p>${esc(c.s)}</p>
              <p style="opacity:.8;">${prev ? "This builds on " + esc(prev.n) + ". " : ""}Turn the page for an exercise.</p>
              <div class="bfolio"><span>${folio + 1}</span><button data-act="${turnFwd}">turn the page ›</button></div></div></div>
            <div class="face face-back"><div class="bin">${exercise}<div class="bfolio"><span>${folio + 2}</span></div></div></div>
          </div>
          <div class="spine" aria-hidden="true"></div>
        </div></div>

      <div><p class="thing-label">your laptop</p>
        <div class="laptop"><div class="lid"><span class="cam" aria-hidden="true"></span><div class="lapscreen">
          <div class="lap-tabs" role="tablist" aria-label="Laptop">
            <button role="tab" aria-selected="${S.lap === "brain"}" class="lap-tab ${S.lap === "brain" ? "lap-on" : ""}" data-act="${act(() => set({ lap: "brain" }))}">◉ BrainU · my brain</button>
            <button role="tab" aria-selected="${S.lap === "nb"}" class="lap-tab ${S.lap === "nb" ? "lap-on" : ""}" data-act="${act(() => set({ lap: "nb" }))}">▤ experiment.ipynb</button></div>
          ${S.lap === "brain" ? brainScreen(steps, i) : `<div class="ipy">
          <div class="ipy-bar"><span class="ipy-file">${esc((nbk ? nbk.title.toLowerCase().replace(/[^a-z0-9*]+/g, "_") : "scratch") + ".ipynb")}</span><span class="ipy-kernel"><span class="ipy-dot"></span>Python 3</span></div>
          <div class="ipy-cell"><span class="ipy-p">md</span><div class="ipy-md"><b>Experiment.</b> ${esc(c.t)}</div></div>
          <div class="ipy-cell"><span class="ipy-p in">In [ ]:</span><pre class="ipy-code">import numpy as np
import matplotlib.pyplot as plt

# your code here</pre></div>
          <div class="ipy-cell" style="align-items:center;"><span></span><div style="display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;">
            <a class="ipy-run" href="${esc(nbk ? nbk.colab : "https://colab.research.google.com/#create=true")}" target="_blank" rel="noopener">▶ ${nbk ? "Open the course notebook in Colab" : "Open a blank notebook in Colab"}</a>
            <span style="font-size:12px;color:#4b5563;">${nbk ? "The book's " + esc(nbk.title) + " notebook." : "No course notebook for this one."}</span></div></div>
        </div>`}</div></div><div class="base" aria-hidden="true"></div></div></div>
      ${mug}

      <div><p class="thing-label">your notepad</p>
        <div class="pad"><div class="spiral" aria-hidden="true">${"<span></span>".repeat(11)}</div>
          <div class="flipstack" style="height:400px;"><div class="padback" aria-hidden="true"></div>
            <section class="leafv ruled ${pad1}" style="z-index:5;" aria-label="Your notes" aria-hidden="${S.pad !== 1}"><div class="pgin">
              <h3 style="font-size:26px;">my notes</h3><label for="mynotes" class="hw" style="opacity:.7;">write what clicked, or what didn't</label>
              <textarea id="mynotes">${esc((S.notes || {})[id] || "")}</textarea>
              <div class="pgfoot"><button data-act="${padBack}">‹ class notes</button><span style="opacity:.7;">2 / 2</span></div></div></section>
            <section class="leafv ruled ${pad0}" style="z-index:6;" aria-label="Class notes" aria-hidden="${S.pad !== 0}"><div class="pgin">
              <h3 style="font-size:26px;">class notes</h3><span class="hw">${esc(c.s)}</span>
              ${prev ? `<span class="hw">builds on → <b>${esc(prev.n)}</b></span>` : ""}
              <span class="hw">remember: ${esc(trunc(c.i[0], 120))}</span>
              <div class="pgfoot"><span></span><button data-act="${padFwd}">flip to my notes ›</button></div></div></section>
          </div></div></div>
    </div>
    <div class="apron"><button class="drawer-front" data-act="${act(() => set({ drawer: true }))}" aria-haspopup="dialog"><span class="knob" aria-hidden="true"></span><span class="plate">my notes drawer · ${notedIds.length} page${notedIds.length === 1 ? "" : "s"}</span></button></div>
    </div>${drawer}

    <div class="lessonbar"><div class="lessonbar-in">
      <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
        <button class="navb hand" style="font-size:22px;" ${prev ? "" : "disabled"} data-act="${act(() => prev && go("lesson", { i: i - 1, picked: null, checked: false }))}">‹ ${esc(prev ? trunc(prev.n, 22) : "")}</button>
        <ol aria-label="Lessons on this path">${segs}</ol>
        <button class="navb hand link" style="font-size:20px;" data-act="${act(() => go("path"))}">my path</button>
      </div>
      <div style="display:flex;align-items:center;gap:16px;">
        ${S.checked ? "" : `<button class="navb hand link" style="font-size:20px;" data-act="${act(() => eraseThen(advance))}">skip the quiz</button>`}
        <button class="am-button" ${!S.checked && S.picked === null ? "disabled" : ""} data-act="${main}">${esc(mainLabel)}</button>
      </div></div></div>`;
  }

  // The laptop's BrainU screen: the whole course as faint neurons in a brain,
  // your path lit up as a route through it, and where you are on it.
  function brainScreen(steps, i) {
    const C = D.C, cx = 162, cy = 104, rx = 112, ry = 60, n = steps.length;
    const rows = n <= 6 ? 2 : n <= 15 ? 3 : 4, per = Math.ceil(n / rows), pts = [];
    for (let k = 0; k < n; k++) {
      const row = Math.floor(k / per), col = k % per, cnt = Math.min(per, n - row * per);
      const y = cy - ry * 0.62 + (rows === 1 ? 0 : (row * ry * 1.24) / (rows - 1));
      const hw = rx * Math.sqrt(Math.max(0.05, 1 - ((y - cy) / (ry * 1.15)) ** 2)) * 0.82;
      const t = cnt === 1 ? 0.5 : col / (cnt - 1), xx = cx - hw + 2 * hw * (row % 2 ? 1 - t : t);
      pts.push([xx + Math.cos(k * 1.7) * 7, y + Math.sin(k * 2.3) * 9]); // a little organic wobble
    }
    // faint neurons: every concept in the course, scattered deterministically
    let seed = 9; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
    const all = Object.keys(C).map(() => { let a, b; do { a = rnd() * 2 - 1; b = rnd() * 2 - 1; } while (a * a + b * b > 1); return [cx + a * (rx + 8), cy + b * (ry + 14)]; });
    const dots = all.map(([a, b]) => `<circle cx="${a.toFixed(1)}" cy="${b.toFixed(1)}" r="1.4" fill="#7c8cff" opacity=".35"/>`).join("");
    const seg = (k) => { const [a, b] = pts[k], [c, d] = pts[k + 1], bend = k % 2 ? 10 : -10;
      return `M${a.toFixed(1)},${b.toFixed(1)} Q${((a + c) / 2 - (d - b) * 0.15).toFixed(1)},${((b + d) / 2 + bend).toFixed(1)} ${c.toFixed(1)},${d.toFixed(1)}`; };
    const passed = S.checked && S.done[steps[i]], lit = (k) => k < i || (k === i && passed);
    const edges = pts.slice(0, -1).map((_, k) => `<path d="${seg(k)}" class="${lit(k) ? "lit" : ""}" stroke="${lit(k) ? "#5eead4" : "#3b4570"}" stroke-width="${lit(k) ? 2.2 : 1.4}" ${lit(k) ? "" : 'stroke-dasharray="3 3"'} fill="none"/>`).join("");
    // Passing a quiz sends a pulse down the route into the next lesson.
    const pulse = S.pulse === i && i < n - 1 ? `<circle r="5" fill="#fde047" class="spark"><animateMotion dur="1.1s" fill="freeze" path="${seg(i)}"/></circle>` : "";
    const nodes = steps.map((id, k) => {
      const [a, b] = pts[k], dn = !!S.done[id], on = k === i, arrive = S.pulse === i && k === i + 1, col = on ? "#fde047" : dn || k < i ? "#5eead4" : "#94a3ff";
      return `<g class="neuron${on ? " neuron-on" : ""}${arrive ? " neuron-arrive" : ""}" role="button" tabindex="0" aria-label="Lesson ${k + 1}: ${esc(C[id].n)}" data-act="${act(() => go("lesson", { i: k, picked: null, checked: false }))}">
        <title>${k + 1}. ${esc(C[id].n)}</title>${on ? `<circle cx="${a.toFixed(1)}" cy="${b.toFixed(1)}" r="11" fill="#fde047" opacity=".18" class="halo"/>` : ""}
        <circle cx="${a.toFixed(1)}" cy="${b.toFixed(1)}" r="${on ? 6 : 4.5}" fill="${k < i || dn || on ? col : "#141a33"}" stroke="${col}" stroke-width="1.6"/>
        <text x="${a.toFixed(1)}" y="${(b + (on ? 3 : 2.6)).toFixed(1)}" text-anchor="middle" font-size="${on ? 7 : 5.5}" font-weight="700" fill="${k < i || dn || on ? "#0b1020" : "#c7d2fe"}">${k + 1}</text></g>`;
    }).join("");
    const learned = steps.filter((id) => S.done[id]).length, pct = Math.round((i / Math.max(1, n - 1)) * 100);
    return `<div class="bu-app">
      <div class="bu-row"><span class="bu-k">your brain · ${Object.keys(C).length} concepts in the course</span><span class="bu-k" style="color:#5eead4;">${learned} learned</span></div>
      <svg class="bu-brain" viewBox="0 0 320 210" role="group" aria-label="Your path through the course, drawn as a brain">
        <defs><radialGradient id="bug" cx="50%" cy="45%" r="60%"><stop offset="0" stop-color="#26306a" stop-opacity=".9"/><stop offset="1" stop-color="#121735" stop-opacity=".9"/></radialGradient></defs>
        <path d="M58,148 C28,138 20,98 40,76 C42,48 70,28 100,32 C116,12 152,8 174,22 C198,8 238,14 254,38 C284,42 304,72 296,100 C310,124 294,152 268,156 C258,176 230,186 208,176 C196,192 166,194 150,180 C132,190 104,186 96,170 C80,174 60,166 58,148 Z" fill="url(#bug)" stroke="#6366f1" stroke-opacity=".7" stroke-width="1.5"/>
        <path d="M240,170 C256,190 286,186 290,166" fill="#1a2049" stroke="#6366f1" stroke-opacity=".5" stroke-width="1.2"/>
        <path d="M206,182 C210,196 214,204 220,208" stroke="#6366f1" stroke-opacity=".5" stroke-width="5" fill="none" stroke-linecap="round"/>
        <g fill="none" stroke="#6366f1" stroke-opacity=".22" stroke-width="1.2" stroke-linecap="round"><path d="M100,40 C120,70 110,96 132,118"/><path d="M174,26 C168,60 190,78 182,112"/><path d="M252,44 C230,70 248,98 230,128"/><path d="M60,120 C90,112 120,140 160,132 C200,124 230,150 270,140"/><path d="M48,88 C80,84 92,64 120,62"/></g>
        ${dots}${edges}${nodes}${pulse}</svg>
      <div class="bu-here"><span class="bu-k">you are here</span><b>${esc(C[steps[i]].n)}</b><span>lesson ${i + 1} of ${n} · goal: ${esc(trunc(goalLabel(), 34))}</span>
        <div class="bu-bar"><span style="width:${pct}%"></span></div></div>
    </div>`;
  }

  function doneScreen() {
    return `<main style="max-width:680px;margin:0 auto;padding:90px 24px;display:flex;flex-direction:column;gap:18px;align-items:center;text-align:center;">
      <span class="hand" style="font-size:26px;">path complete</span><h1 style="margin:0;font:400 52px/1.05 var(--am-font-display);">${esc(goalLabel())}</h1>
      <p style="margin:0;font-size:17px;">You worked through ${path().steps.length} lessons and passed ${S.passed} pop quizzes.</p>
      <button class="am-button" data-act="${act(() => go("q2", { pickBg: S.bg, pickGoal: null, started: false }))}">Pick new goals</button></main>`;
  }

  function explore() {
    const items = [["3D graph", "Fly through every concept and how they connect."], ["arXivis", "Recent papers, each with a 30-second explainer."], ["Podcast", "Listen to a concept explained."], ["Open problems", "Research gaps the graph surfaces."], ["Dashboard", "What you've learned so far."]];
    return `<main style="max-width:980px;margin:0 auto;padding:48px 24px;display:flex;flex-direction:column;gap:20px;">
      <h1 style="margin:0;font:400 46px/1 var(--am-font-display);">Explore</h1>
      <p style="margin:0;font-size:17px;">Everything else in Brain University, for when you want to wander. The full app is at <a href="Brain%20University.html">Brain University.html</a>.</p>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:18px;">${items.map(([t, d]) => `<section class="am-card"><h2 class="am-card__title">${t}</h2><p style="margin:0;">${d}</p></section>`).join("")}</div></main>`;
  }

  function render() {
    acts = [];
    if (!D) return;
    const scr = S.screen;
    let body;
    if (scr === "home" && S.goal && path().steps.length) body = home();
    else if (scr === "path" && S.goal) body = pathScreen();
    else if (scr === "lesson" && S.goal && path().steps.length) body = lesson();
    else if (scr === "done") body = doneScreen();
    else if (scr === "explore") body = explore();
    else { if (scr !== "q2") S.screen = "q1"; body = questions(); }
    // Keep the textarea's focus and caret across re-renders.
    const ta = document.activeElement && document.activeElement.id === "mynotes" ? [document.activeElement.selectionStart] : null;
    document.body.toggleAttribute("data-room", S.screen === "lesson");
    app.innerHTML = nav() + body;
    if (S.screen === "path") drawString();
    tickClock();
    if (ta) { const t = document.getElementById("mynotes"); if (t) { t.focus(); t.setSelectionRange(ta[0], ta[0]); } }
  }

  fetch("prototype/course.json").then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then((data) => { D = data; if (S.goal) { S.goal = S.goal.filter((g) => D.C[g]); if (!S.goal.length) { S.goal = null; S.screen = "q1"; } } render(); })
    .catch(() => { app.innerHTML = `<p class="loading">The course didn't load. Run a local server in the design folder (python3 -m http.server 8000) and reload.</p>`; });
})();
